--- /dev/null
+++ b/shell/nestedconfigview.cpp
@@ -0,0 +1,54 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.0-or-later
+*/
+
+#include "nestedconfigview.h"
+
+#include <Plasma/Containment>
+
+static bool isInside(Plasma::Applet *applet, Plasma::Applet *outer)
+{
+    // Applets of a top-level containment get their own settings window, as before
+    if (applet == outer || outer->containment() == outer) {
+        return false;
+    }
+    for (QObject *parent = applet->parent(); parent; parent = parent->parent()) {
+        if (parent == outer) {
+            return true;
+        }
+    }
+    return false;
+}
+
+NestedConfigView::~NestedConfigView()
+{
+    close();
+}
+
+bool NestedConfigView::show(PlasmaQuick::ConfigView *parentView, Plasma::Applet *applet)
+{
+    if (m_view && m_view->applet() == applet) {
+        m_view->requestActivate();
+        return true;
+    }
+    if (!applet || !parentView || !isInside(applet, parentView->applet())) {
+        return false;
+    }
+
+    close();
+    m_view = new PlasmaQuick::ConfigView(applet);
+    m_view->init();
+    m_view->setTransientParent(parentView);
+    m_view->show();
+    m_view->requestActivate();
+    return true;
+}
+
+void NestedConfigView::close()
+{
+    if (m_view) {
+        m_view->deleteLater();
+    }
+}
diff --git a/shell/nestedconfigview.h b/shell/nestedconfigview.h
new file mode 100644
index 0000000000..b9c639d9d6
--- /dev/null
+++ b/shell/nestedconfigview.h
@@ -0,0 +1,33 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.0-or-later
+*/
+
+#pragma once
+
+#include <PlasmaQuick/ConfigView>
+
+#include <QPointer>
+
+/**
+ * The settings window of an applet inside the applet whose settings are open,
+ * such as an entry of the System Tray. It opens on top of that window instead
+ * of replacing it, so its unapplied changes are kept.
+ */
+class NestedConfigView
+{
+public:
+    ~NestedConfigView();
+
+    /**
+     * Shows the settings of @p applet if they are already open here, or if
+     * @p applet is inside the applet configured by @p parentView.
+     * @returns whether the settings of @p applet are now shown
+     */
+    bool show(PlasmaQuick::ConfigView *parentView, Plasma::Applet *applet);
+    void close();
+
+private:
+    QPointer<PlasmaQuick::ConfigView> m_view;
+};
